import math


def progressive_bands(bands):
    if isinstance(bands, (str, bytes)):
        raise TypeError('bands must be iterable')
    try:
        raw_bands = list(bands)
    except TypeError as exc:
        raise TypeError('bands must be iterable') from exc
    if not raw_bands:
        raise ValueError('at least one band is required')
    prepared = []
    width = None
    for raw_band in raw_bands:
        if isinstance(raw_band, (str, bytes)):
            raise TypeError('each band must be iterable')
        try:
            band = list(raw_band)
        except TypeError as exc:
            raise TypeError('each band must be iterable') from exc
        if not band:
            raise ValueError('bands must not be empty')
        if width is None:
            width = len(band)
        if len(band) != width:
            raise ValueError('band widths must match')
        for value in band:
            if isinstance(value, bool) or not isinstance(value, (int, float)):
                raise TypeError('band values must be numeric')
            if not math.isfinite(value):
                raise ValueError('band values must be finite')
        prepared.append(band[:])
    result = [prepared[0][:]]
    for index in range(1, len(prepared)):
        result.append([
            current + previous
            for current, previous in zip(prepared[index], prepared[index - 1])
        ])
    return result
```

